// Issue templates for the fixture data: realistic errors per platform, each
// with the frame where it happens (with source code around the line), plus
// libraries of deeper frames that are mixed in.

import type { Level } from '@/api/types'

export interface FrameSpec {
  file: string
  abs?: string
  fn: string
  module?: string
  line: number
  col?: number
  inApp: boolean
  pre?: string[]
  code?: string
  post?: string[]
  vars?: Record<string, unknown>
}

export interface Template {
  platform: 'javascript' | 'node' | 'python' | 'php' | 'go'
  type?: string
  value: string
  /** Log message instead of an exception. */
  message?: boolean
  level: Level
  culprit: string
  handled: boolean
  mechanism: string
  top: FrameSpec
  /** Frames between the top frame and the library frames (caller chain). */
  callers?: FrameSpec[]
  cause?: { type: string; value: string; top: FrameSpec }
  transaction: string
  weight?: number
}

